  (art_cls_needs_populate c cl = true -> cl_mu cl + 262144 <= 3758096384 /\ art_cls_mfa' cl (Z.of_nat (length (cl_free cl)) + art_cls_new c cl) <= 536870912) ->
  art_cls_ok c (art_cls_pre_take c cl).
Proof.
